// Year 8 geography, part 2: storms and UK extremes, UK landscapes, farming, water and food,
// tourism, deserts, the polar regions, oceans, Africa and Nigeria, China, India, Brazil, the EU,
// regeneration, fieldwork and GIS, sustainability, and more world places. GCSE-style written
// answers in most topics, marked by a grown-up. Greek links where they fit; characters are original.

const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `geography.m.${id}`, topic: `geography.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({
  id: `geography.m.${id}`, topic: `geography.${topic}`, kind: 'mcq', prompt,
  options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra,
});
const order = (id, topic, prompt, items, labels, explain) => ({ id: `geography.m.${id}`, topic: `geography.${topic}`, kind: 'order', prompt, items, labels, explain });
// each written answer comes with a short resource of key facts, as GCSE questions often do
const written = (id, topic, prompt, hints, model, extra = {}) => ({ id: `geography.m.${id}`, topic: `geography.${topic}`, kind: 'written', prompt, hints, model, words: [60, 250], passage: BRIEF[id], passageSource: 'Key facts: briefing notes written for this app', ...extra });
const BRIEF = {
  'ts.w': 'Typhoon Haiyan, Philippines, November 2013: storm surge of several metres at Tacloban; more than 6,000 deaths; about 4 million people displaced.\nHurricane Katrina, USA, August 2005: category 3 at landfall; levees failed and about 80% of New Orleans flooded; about 1,800 deaths; damage over $100 billion.',
  'uk.w': 'The “Beast from the East”, late February to early March 2018: easterly winds from Siberia, then Storm Emma from the south. Heavy snow and temperatures below −10 °C in places. Red weather warnings issued; schools, roads and railways closed; the army helped stranded drivers.',
  'ul.w': 'Dartmoor: granite (igneous, hard, impermeable): high moorland, bogs, tors.\nSouth Downs and Dover: chalk (sedimentary, soft, porous): rolling hills, dry valleys, white cliffs.\nMalham, Yorkshire Dales: Carboniferous limestone: limestone pavement, caves, gorges.\nThe Tees–Exe line divides upland from lowland Britain.',
  'fm.w': 'East Anglia: flat; fertile soils; about 600 mm of rain a year; warm summers. Main farming: cereals and sugar beet.\nWales and the Lake District uplands: steep slopes; over 1,500 mm of rain a year in places; thin, acidic soils. Main farming: sheep, some cattle.',
  'wf.w': 'Grand Ethiopian Renaissance Dam, Blue Nile, Ethiopia: one of Africa’s largest hydroelectric dams; Egypt depends on the Nile for almost all its fresh water.\nAtatürk Dam, Euphrates, Turkey: irrigation and power; Syria and Iraq downstream.\nThree Gorges Dam, Yangtze, China: more than a million people relocated.',
  'tr.w': 'Greece: tens of millions of international visitors a year; tourism is one of the largest parts of the economy. Many jobs are seasonal. Popular islands face summer water shortages. The Acropolis now uses timed tickets to limit crowds. Venice has trialled an entry fee for day visitors.',
  'ds.w': 'The Sahel: a semi-arid belt south of the Sahara, about 200–600 mm of rain a year, falling unreliably. Rapidly growing population. Many families depend on herding and farming, and on wood for cooking. The Great Green Wall began in 2007.',
  'pl.w': 'Antarctica holds about 90% of the world’s ice. If its ice and Greenland’s melted, sea levels would rise by tens of metres (over centuries). Arctic summer sea ice has shrunk sharply since satellite records began in 1979. White ice reflects most sunlight; dark ocean absorbs most of it.',
  'oc.w': 'About 8 million tonnes of plastic are estimated to reach the oceans each year. Microplastics have been found from the deepest trenches to Arctic ice.\nThe Grand Banks cod fishery off Canada collapsed and was closed in 1992; about 30,000 people lost their jobs.',
  'af.w': '54 countries; over 1.4 billion people; median age under 20.\nPhysical: Sahara, Congo rainforest, Great Rift Valley, Kilimanjaro (5,895 m), the Nile.\nEconomy: some of the world’s fastest-growing economies; M-Pesa mobile money launched in Kenya in 2007.\nWell over 1,000 languages.',
  'ng.w': 'Nigeria: over 200 million people, the most in Africa. Oil provides most export earnings. Oil spills in the Niger Delta have damaged farmland, fishing grounds and mangroves. Growing sectors: telecommunications, services, farming and film (Nollywood). Independence from Britain in 1960.',
  'cn.w': 'Three Gorges Dam, Yangtze River, completed in the 2000s: one of the world’s largest power stations. Reservoir about 600 km long. More than a million people relocated; towns, farmland and archaeological sites flooded. Reduces flood risk downstream and allows large ships further inland.',
  'in.w': 'Monsoon: most rain falls June–September. Over half of India’s workers depend on farming.\nThe Ganges: rises in the Himalayas; sacred to Hindus; supplies hundreds of millions of people.\nThe Himalayas: snow and glacier meltwater; earthquakes and landslides.\nMawsynram, north-east India: over 11 m of rain in a year.',
  'bz.w': 'About 60% of the Amazon is in Brazil. Main causes of clearing: cattle ranching, soya, logging, mining, roads and dams. The forest stores huge amounts of carbon and recycles rainfall that falls far away. Indigenous territories are generally cleared much less than surrounding land.',
  'eu.w': 'EU: 27 members since the UK left on 31 January 2020. Euro: used by 20 EU countries. Schengen area: no routine passport checks at most internal borders; includes some non-EU countries. Good Friday Agreement (1998): supported peace in Northern Ireland with an open border.',
  'rg.w': 'London Docklands: docks closed between the 1960s and 1981. London Docklands Development Corporation from 1981. Canary Wharf offices, the Docklands Light Railway (1987), London City Airport. Tens of thousands of new jobs, many in finance. House prices rose sharply. Queen Elizabeth Olympic Park, Stratford, for 2012.',
  'fw.w': 'Hypothesis: environmental quality improves with distance from the town centre.\nUseful methods: a transect; systematic sampling every 200 m; an environmental quality survey (scores from −2 to +2); traffic counts; photographs.\nUseful secondary data: maps of crime, house prices or air quality.',
  'su.w': 'Sustainable development (Brundtland Report, 1987): meeting the needs of the present without compromising the ability of future generations to meet their own needs.\nThree parts: environmental, social and economic.\nThe UN agreed 17 Sustainable Development Goals in 2015, for 2030.',
  'dc.w': 'Cliffs retreating about 1–2 m a year; about 300 homes at risk within 50 years.\nOption A, sea wall: very expensive per metre; reflects waves; may increase erosion further along the coast.\nOption B, rock armour: cheaper; absorbs wave energy; lasts a few decades.\nOption C, managed retreat: cheapest now; homes and businesses lost; most natural.',
  'um.w': 'Burgess model (1920s): rings from the centre: CBD; inner city (factories, 1800s terraces); inner suburbs; outer suburbs; rural–urban fringe.\nLondon examples: the City (CBD); Hackney (Victorian terraces); outer boroughs such as Bromley (suburbs); Canary Wharf (regenerated docks with skyscrapers).',
  'rc.w': 'The Nile: Ethiopia’s Grand Ethiopian Renaissance Dam is upstream of Sudan and Egypt.\nThe Arctic: shrinking sea ice is opening routes and seabed resources; Russia, Canada, Norway, Denmark (Greenland) and the USA border it.\nIndus Waters Treaty, 1960: shares the rivers of the Indus basin between India and Pakistan.',
};
const C = { formats: ['choice'] };

const topics = [
  { id: 'geography.storms', title: 'Tropical storms', kind: 'facts', prereqs: ['geography.weather'], batch: 5, intro: 'Hurricanes, typhoons and cyclones are the same thing in different oceans: giant spinning storms fed by warm seas. Poseidon got the blame for storms at sea; today satellites track them days in advance.', teach: 'Explain the conditions a tropical storm needs to form.', talk: 'Ask {him} why tropical storms never form right on the Equator.' },
  { id: 'geography.uk-extremes', title: 'Extreme weather in the UK', kind: 'facts', prereqs: ['geography.weather'], batch: 5, intro: 'The UK’s weather is usually mild, but it has extremes: snow from Siberia, droughts, named storms and record heat. Each one tests how ready we are.', teach: 'Explain what caused the “Beast from the East” in 2018.', talk: 'Ask {him} which UK storm names {she} remembers, and how they are chosen.' },
  { id: 'geography.uk-landscapes', title: 'The UK’s physical landscapes', kind: 'facts', prereqs: ['geography.ice'], batch: 5, intro: 'Under every British landscape is its rock. Hard, old rocks make the uplands of the north and west; younger, softer rocks make the lowlands of the south and east.', teach: 'Explain the Tees–Exe line and what it divides.', talk: 'Next time you are on a walk, ask {him} what rock might be underneath and how {she} could tell.' },
  { id: 'geography.farming', title: 'Soils and farming', kind: 'facts', prereqs: ['geography.uk-landscapes'], batch: 5, intro: 'Farming depends on soil, climate and relief. That is why eastern England grows wheat and the wet hills of the west raise sheep.', teach: 'Explain why arable farming is common in East Anglia.', talk: 'Look at where the food in your fridge comes from and ask {him} about food miles.' },
  { id: 'geography.water-food', title: 'Water and food security', kind: 'facts', prereqs: ['geography.development'], batch: 5, intro: 'Water and food are unevenly shared. Rivers that cross borders, like the Nile and the Euphrates, can bring countries together or push them apart.', teach: 'Explain what “virtual water” means, with an example.', talk: 'Ask {him} how much water {she} thinks is used to make one burger.' },
  { id: 'geography.tourism', title: 'Tourism and its impacts', kind: 'facts', prereqs: ['geography.global'], batch: 5, intro: 'Tourism is one of the world’s biggest industries. It brings jobs and money, but too many visitors can damage the very places they come to see, from Venice to the Acropolis.', teach: 'Explain the stages of Butler’s tourism life cycle.', talk: 'Ask {him} whether {she} thinks famous places should limit visitors.' },
  { id: 'geography.deserts', title: 'Deserts and desertification', kind: 'facts', prereqs: ['geography.biomes'], batch: 5, intro: 'Deserts are defined by dryness, not heat: Antarctica is the biggest of all. On the edges of the Sahara, the Sahel shows how land can slowly turn to desert, and how people are fighting back.', teach: 'Explain three causes of desertification in the Sahel.', talk: 'Ask {him} why the Great Green Wall is being planted.' },
  { id: 'geography.polar', title: 'The polar regions', kind: 'facts', prereqs: ['geography.biomes'], batch: 5, intro: 'The Arctic is an ocean surrounded by land; Antarctica is a continent surrounded by ocean. Both are warming fast, and what happens there affects everyone.', teach: 'Explain how Antarctica is protected by international agreement.', talk: 'Ask {him} why melting Arctic sea ice does not raise sea levels much but melting Antarctic ice does.' },
  { id: 'geography.oceans', title: 'Oceans under pressure', kind: 'facts', prereqs: ['geography.climate'], batch: 5, intro: 'Oceans cover about 71% of the Earth. They feed billions, steady the climate and hold most of its life, but plastic, overfishing and warming are taking their toll.', teach: 'Explain how plastic ends up in the middle of the Pacific.', talk: 'Count the single-use plastics in your bin this week with {him}.' },
  { id: 'geography.africa', title: 'Africa: a continent of 54 countries', kind: 'facts', prereqs: ['geography.places'], batch: 5, intro: 'Africa is not a country. It has 54 of them, well over a thousand languages, the world’s youngest population and some of its fastest-growing cities and tech industries.', teach: 'Explain two common stereotypes about Africa and why they are misleading.', talk: 'Ask {him} to name five African countries and one fact about each.' },
  { id: 'geography.nigeria', title: 'Nigeria in depth', kind: 'facts', prereqs: ['geography.africa'], batch: 5, intro: 'Nigeria is Africa’s most populous country and one of its biggest economies. Oil, film, farming and the megacity of Lagos make it a classic GCSE case study of a newly emerging economy.', teach: 'Explain the advantages and problems oil has brought to Nigeria.', talk: 'Ask {him} what Nollywood is.' },
  { id: 'geography.china', title: 'China’s rise', kind: 'facts', prereqs: ['geography.global'], batch: 5, intro: 'In forty years China went from a mostly rural country to the world’s workshop. Its choices on population, energy and cities affect the whole planet.', teach: 'Explain one benefit and one problem of the Three Gorges Dam.', talk: 'Look at how many things in your house were made in China and ask {him} why.' },
  { id: 'geography.india', title: 'India: monsoon, rivers and change', kind: 'facts', prereqs: ['geography.weather'], batch: 5, intro: 'India is now the world’s most populous country. Its farming depends on the monsoon, its rivers are sacred, and its cities are hubs of the global economy.', teach: 'Explain why the monsoon matters so much to India.', talk: 'Ask {him} what causes the monsoon.' },
  { id: 'geography.brazil', title: 'Brazil and the Amazon', kind: 'facts', prereqs: ['geography.biomes'], batch: 5, intro: 'Brazil holds most of the Amazon, the largest rainforest on Earth. Who gets to decide its future: farmers, miners, indigenous peoples, the government, or the world?', teach: 'Explain why the Amazon matters beyond Brazil.', talk: 'Ask {him} whether {she} thinks other countries should pay Brazil to protect the rainforest.' },
  { id: 'geography.eu', title: 'Europe, the EU and borders', kind: 'facts', prereqs: ['geography.places'], batch: 5, intro: 'Borders are drawn by people. The European Union removed many of them for trade and travel; Brexit put some back. Borders shape trade, migration and identity.', teach: 'Explain the difference between the EU, the euro area and the Schengen area.', talk: 'Ask {him} what changed for travellers after the UK left the EU.' },
  { id: 'geography.regeneration', title: 'UK cities and regeneration', kind: 'facts', prereqs: ['geography.cities'], batch: 5, intro: 'When old industries closed, whole districts of British cities emptied. Regeneration brings them back to life, but who benefits?', teach: 'Explain the difference between brownfield and greenfield sites.', talk: 'Ask {him} about a part of your nearest city that has been rebuilt.' },
  { id: 'geography.fieldwork', title: 'Fieldwork, enquiry and GIS', kind: 'facts', prereqs: ['geography.maps'], batch: 5, intro: 'Geographers go out and measure. Good fieldwork starts with a question, uses fair sampling and ends by asking how reliable the results are. GIS layers data on maps to reveal patterns.', teach: 'Explain the difference between random, systematic and stratified sampling.', talk: 'Plan a mini fieldwork question with {him}: is our street busier at 8 am or 11 am?' },
  { id: 'geography.sustainability', title: 'Sustainability and the global goals', kind: 'facts', prereqs: ['geography.development'], batch: 5, intro: 'Sustainable development meets today’s needs without stealing from the future. In 2015 every UN member agreed 17 Sustainable Development Goals for 2030.', teach: 'Explain what sustainable development means, using an example.', talk: 'Ask {him} which of the 17 global goals {she} thinks matters most.' },
  { id: 'geography.places-2', title: 'World places: more countries and capitals', kind: 'facts', prereqs: ['geography.places'], batch: 6, intro: 'Twenty-six more countries to find, from Argentina to New Zealand, and their capitals. Several capitals are not the biggest city: Canberra, Ottawa, Brasília and Pretoria were chosen or built on purpose.', teach: 'Name three capitals that are not their country’s largest city.', talk: 'Quiz each other on capitals during a car journey.' },
  // GCSE tasters
  { id: 'geography.decisions', title: 'Making decisions: issue evaluation (GCSE taster)', kind: 'facts', tier: 'stretch', prereqs: ['geography.sustainability'], batch: 5, intro: 'GCSE geography ends with an issue to judge: a new dam, a coastal defence, a tourist resort. You weigh stakeholders, costs, benefits and sustainability, then make and defend a decision.', teach: 'Explain how to structure a decision-making answer.', talk: 'Pick a local issue (a new housing estate, a bypass) and ask {him} who would be for and against it.' },
  { id: 'geography.urban-models', title: 'Inside the city: urban models (GCSE taster)', kind: 'facts', tier: 'stretch', prereqs: ['geography.regeneration'], batch: 5, intro: 'Cities are not random. Models like Burgess’s rings show how land use, building age and wealth change as you travel out from the centre.', teach: 'Explain the zones of the Burgess model.', talk: 'On a drive into town, ask {him} to spot when you move from suburbs to inner city to the CBD.' },
  { id: 'geography.resources-conflict', title: 'Resources and conflict (GCSE taster)', kind: 'facts', tier: 'stretch', prereqs: ['geography.water-food', 'geography.polar'], batch: 5, intro: 'When resources are scarce or newly reachable, countries compete for them: shared rivers, Arctic seabed, rare metals for phones. Geography helps explain where tensions arise.', teach: 'Explain why the Arctic is becoming more contested.', talk: 'Ask {him} which resources {her} phone needs, and where they might come from.' },
];

