const items = [
  // --- tropical storms
  mcq('ts.conditions', 'storms', 'Which set of conditions does a tropical storm need to form?', [['Sea water above about 27 °C, away from the Equator', true], ['Cold water and strong winds blowing from the poles', false, 'They are fed by warm water: heat and moisture are their fuel.'], ['Any stretch of sea, as long as it is windy', false, 'They need very warm water and the spin from the Earth’s rotation.'], ['Warm land with high mountains nearby', false, 'They form over the ocean and weaken over land.']], 'Warm water evaporates into rising air; the Coriolis effect, from the Earth’s spin, sets the storm turning.'),
  mcq('ts.equator', 'storms', 'Why do tropical storms not form right on the Equator?', [['The Earth’s spin is too weak there to turn them', true], ['The sea there is too cold for them to form', false, 'The water at the Equator is very warm.'], ['There is almost no wind at the Equator', false, 'There is wind; the problem is the lack of spin.'], ['They do form there, many times each year', false, 'They almost never form within about 5° of the Equator.']], 'The Coriolis effect is zero at the Equator and grows towards the poles.'),
  fact('ts.names', 'storms', 'In the north-west Pacific, near Japan and the Philippines, a tropical storm is called a…', 'typhoon', ['hurricane', 'cyclone', 'tornado'], 'Hurricane (Atlantic and north-east Pacific), typhoon (north-west Pacific), cyclone (Indian Ocean and South Pacific). Same storm, different names.', { accept: ['a typhoon'] }),
  mcq('ts.eye', 'storms', 'What is the eye of a tropical storm like?', [['Calm, with light winds', true], ['The windiest part of the storm', false, 'The strongest winds are in the eyewall around it.'], ['Full of heavy hail', false, 'The eye is calm, as sinking air clears the cloud.'], ['Much colder than the rest', false, 'It is not especially cold.']], 'People caught in the eye sometimes think the storm is over, then the other side of the eyewall arrives.'),
  fact('ts.scale', 'storms', 'Which scale rates hurricanes from category 1 to 5 by wind speed?', 'the Saffir–Simpson scale', ['the Richter scale', 'the Beaufort scale', 'the Mercalli scale'], 'Category 5 means sustained winds over about 250 km/h. (The Beaufort scale is for ordinary winds; Richter and Mercalli are for earthquakes.)', C),
  mcq('ts.surge', 'storms', 'Typhoon Haiyan hit the Philippines in 2013 and killed more than 6,000 people. What caused most of the deaths?', [['A storm surge flooding low coasts', true], ['Hailstones the size of tennis balls', false, 'Hail is rare in tropical storms.'], ['Lightning strikes on crowded towns', false, 'Lightning was not the main killer.'], ['Landslides on volcanic slopes', false, 'Landslides happened, but the surge killed far more.']], 'Low pressure and fierce winds raise the sea by several metres, flooding coastal towns.'),
  mcq('ts.katrina', 'storms', 'Hurricane Katrina (2005) flooded about 80% of New Orleans. Why was a rich country hit so hard?', [['Its levees failed', true], ['The USA had no warning at all', false, 'Forecasters warned days in advance.'], ['It was the strongest hurricane ever', false, 'It was category 3 at landfall.'], ['Nobody had been told to leave', false, 'A mandatory evacuation was ordered, but many could not leave.']], 'About 1,800 people died. Poorer residents without cars found it hardest to evacuate.'),
  mcq('ts.land', 'storms', 'Why do tropical storms weaken when they move over land?', [['They lose their warm, moist air', true], ['The land’s magnetism pulls them apart', false, 'Magnetism has nothing to do with it.'], ['Trees absorb the wind', false, 'Friction helps, but the main reason is losing their fuel.'], ['They gain strength from hills', false, 'They weaken quickly, though their rain can still cause floods far inland.']], 'Their fuel is warm water. Over land they run out of it.'),
  written('ts.w', 'storms', 'Explain why the effects of a tropical storm can be greater in a poorer country than in a richer one. Use examples.', ['A clear point about wealth and preparation', 'Warnings, evacuation and building quality', 'An example from a poorer country (e.g. Haiyan, Philippines 2013)', 'An example from a richer country, including any exceptions (e.g. Katrina, 2005)', 'A short conclusion'], 'Poorer countries usually suffer more deaths because they have less money to prepare and respond. Warning systems may not reach everyone, and many people live in lightweight homes on low coasts, so a storm surge can sweep them away. When Typhoon Haiyan hit the Philippines in 2013, the surge flooded Tacloban and more than 6,000 people died. Richer countries can afford satellites, strong buildings, evacuation plans and emergency services, so deaths are usually lower, although damage costs are higher because property is worth more. However, wealth does not guarantee safety: Hurricane Katrina killed about 1,800 people in New Orleans in 2005 because the levees failed and poorer residents could not evacuate. So wealth reduces risk, but only if it is used to protect everyone.'),

  // --- UK extremes
  mcq('uk.beast', 'uk-extremes', 'What caused the “Beast from the East” in February and March 2018?', [['Freezing easterly winds from Siberia', true], ['Ash from a volcanic eruption in Iceland', false, 'No eruption was involved.'], ['A tropical storm that drifted north', false, 'It was extreme cold, not a tropical storm.'], ['The Gulf Stream stopping for a month', false, 'The North Atlantic Drift did not stop.']], 'Usually our weather comes from the mild Atlantic. When the wind swings round to the east in winter, it brings continental cold. Storm Emma added heavy snow.'),
  mcq('uk.names', 'uk-extremes', 'Why have UK storms been given names since 2015?', [['So people take warnings seriously', true], ['To honour famous British scientists', false, 'Names are chosen from public suggestions, not to honour anyone.'], ['Because they are all hurricanes', false, 'Ordinary deep depressions are named when they are likely to cause severe impacts.'], ['It is a tradition from Roman times', false, 'It started in 2015.']], 'The Met Office and Met Éireann (and now the Dutch weather service) name storms likely to bring amber or red warnings.'),
  fact('uk.cold', 'uk-extremes', 'The UK’s lowest recorded temperature, −27.2 °C, was measured in which country of the UK?', 'Scotland', ['Wales', 'England', 'Northern Ireland'], 'It has been reached three times in the Scottish Highlands: at Braemar (1895 and 1982) and Altnaharra (1995).', { accept: ['scotland'] }),
  mcq('uk.drought', 'uk-extremes', 'Which of these is a typical response to drought in the UK?', [['A hosepipe ban', true], ['Cloud seeding over every city', false, 'The UK does not routinely seed clouds.'], ['Closing schools to save water', false, 'Drought does not close schools.'], ['Building new sea walls', false, 'Sea walls protect against coastal flooding, not drought.']], 'The long, hot summer of 1976 brought standpipes in streets; 2022 brought hosepipe bans across much of England.'),
  mcq('uk.why-floods', 'uk-extremes', 'Why might extreme rainfall in the UK become more common as the climate warms?', [['Warmer air holds more water vapour', true], ['Warmer air holds less water vapour', false, 'It is the opposite: about 7% more water vapour per °C.'], ['The UK is drifting towards the Equator', false, 'Plates move only a few centimetres a year.'], ['Rainfall will not change at all', false, 'Scientists expect wetter winters and more intense downpours.']], 'This is why wetter winters and more intense summer storms are both expected.'),
  mcq('uk.warning', 'uk-extremes', 'What does a Met Office RED weather warning mean?', [['Dangerous weather: take action now', true], ['Be aware of minor disruption', false, 'That is yellow.'], ['Be prepared for travel delays', false, 'That is amber.'], ['Very hot sun: wear sun cream', false, 'Heat can bring warnings too, but red means danger to life.']], 'Yellow, amber, red: from “be aware” to “take action”.'),
  written('uk.w', 'uk-extremes', 'Explain how one extreme weather event affected people in the UK and how they responded.', ['Name the event and when it happened', 'What caused it (briefly)', 'At least two effects on people (travel, schools, health, economy)', 'How people and authorities responded', 'A judgement on how well the UK coped'], 'The “Beast from the East” in late February and early March 2018 brought bitterly cold easterly winds from Siberia, and when it met Storm Emma heavy snow fell across much of the UK. Roads and railways closed, thousands of schools shut, and some drivers were stranded overnight on motorways. Supermarkets ran short of bread and milk, and burst pipes left homes without water when the thaw came. The Met Office issued rare red warnings, councils gritted main roads and the army helped to rescue stranded people. The UK coped reasonably well with warnings and emergency help, but the disruption showed that a country used to mild winters is not well equipped for heavy snow.'),

  // --- UK landscapes
  mcq('ul.tees', 'uk-landscapes', 'What does the Tees–Exe line roughly divide?', [['Upland from lowland Britain', true], ['England from Scotland', false, 'It runs from the River Tees in the north-east to the River Exe in Devon.'], ['Wet farmland from dry farmland', false, 'Rainfall differs too, but the line is mainly about rock and height.'], ['Cities from the countryside', false, 'Both sides have cities and countryside.']], 'Draw a line from the mouth of the Tees to the mouth of the Exe: hills and mountains mostly lie to the north-west.'),
  fact('ul.granite', 'uk-landscapes', 'Dartmoor’s tors are made of which hard igneous rock?', 'granite', ['chalk', 'limestone', 'clay'], 'Granite formed from magma cooling slowly underground. Weathering along its joints leaves the blocky tors.', { accept: ['granite'] }),
  mcq('ul.chalk', 'uk-landscapes', 'The White Cliffs of Dover and the South Downs are made of which rock?', [['Chalk', true], ['Granite', false, 'Granite is hard and grey, found in places like Dartmoor and the Cairngorms.'], ['Slate', false, 'Slate is in North Wales and the Lake District.'], ['Basalt', false, 'Basalt forms the Giant’s Causeway in Northern Ireland.']], 'Chalk is a soft, white limestone made from the skeletons of tiny sea creatures.'),
  mcq('ul.karst', 'uk-landscapes', 'Clints and grikes (blocks and cracks) at Malham Cove form a limestone pavement. How did the grikes form?', [['Acid rainwater dissolved the joints', true], ['Earthquakes cracked the rock apart', false, 'Weathering, not earthquakes.'], ['Farmers dug them as drains', false, 'They are natural.'], ['Lava cooled and shrank into blocks', false, 'Limestone is sedimentary, not volcanic.']], 'This dissolving is called carbonation, a kind of chemical weathering.'),
  fact('ul.ben', 'uk-landscapes', 'What is the highest mountain in the UK?', 'Ben Nevis', ['Snowdon', 'Scafell Pike', 'Slieve Donard'], 'Ben Nevis is 1,345 m high, in the Scottish Highlands near Fort William.', { accept: ['ben nevis'] }),
  fact('ul.lough', 'uk-landscapes', 'What is the largest lake in the UK by area?', 'Lough Neagh', ['Loch Ness', 'Windermere', 'Loch Lomond'], 'Lough Neagh in Northern Ireland covers about 390 km². Loch Ness holds more water because it is so deep.', { accept: ['lough neagh'] }),
  fact('ul.park', 'uk-landscapes', 'Which was the UK’s first national park, created in 1951?', 'the Peak District', ['Snowdonia (Eryri)', 'the Lake District', 'Dartmoor'], 'The Peak District, between Manchester and Sheffield, is within an hour of millions of people.', { accept: ['peak district'] }),
  mcq('ul.weathering', 'uk-landscapes', 'Freeze–thaw weathering is common on British mountains. How does it work?', [['Ice expands in cracks', true], ['The Sun melts the rock surface', false, 'Rock does not melt in sunshine.'], ['Plant roots dissolve the rock', false, 'Roots can widen cracks, but that is biological weathering.'], ['Waves crash against it', false, 'That is erosion at the coast.']], 'Water expands by about 9% when it freezes. The broken rock collects as scree below.'),
  written('ul.w', 'uk-landscapes', 'Explain how rock type affects the landscape of the UK. Use two contrasting examples.', ['A point linking rock hardness to relief', 'A first example (e.g. granite on Dartmoor: tors, moorland)', 'A second, contrasting example (e.g. chalk downs or limestone at Malham)', 'Mention of weathering or erosion processes', 'Link to the upland–lowland divide'], 'Rock type strongly shapes the UK’s landscape because hard rocks resist erosion and soft rocks wear away. On Dartmoor, hard granite forms high, boggy moorland, and freeze–thaw and other weathering along its joints have left blocky tors standing above the land. In contrast, chalk in south-east England is softer and porous, so it forms gentle rolling hills such as the South Downs, with few streams because rain soaks straight in; where chalk meets the sea, it forms white cliffs like Dover. Overall, older, harder rocks in the north and west make upland Britain, while younger, softer rocks in the south and east make lowland Britain, which is roughly the Tees–Exe line.'),

  // --- farming
  mcq('fm.east', 'farming', 'Why is arable farming (growing crops) common in East Anglia?', [['Flat, fertile land and dry summers', true], ['Its mountains shelter the crops', false, 'East Anglia is one of the flattest parts of the UK.'], ['It rains almost every day', false, 'It is one of the driest parts of the UK.'], ['Sheep cannot survive on its grass', false, 'Sheep could, but crops make better use of the land.']], 'Wheat, barley and sugar beet are major crops there.'),
  mcq('fm.west', 'farming', 'Why is pastoral farming (raising animals) common in Wales and the Lake District?', [['Wet, steep land suits grass', true], ['The land is too flat for crops', false, 'It is hilly.'], ['It is too dry for most crops', false, 'It is wet, not dry: grass grows well.'], ['Its soils are the richest in Britain', false, 'Machinery struggles on steep, wet land.']], 'Hill sheep farming is typical of the uplands.'),
  fact('fm.intensive', 'farming', 'Farming that uses lots of money, machinery, fertiliser or labour on a small area to get high yields is called…', 'intensive farming', ['extensive farming', 'subsistence farming', 'nomadic herding'], 'Extensive farming uses large areas with low inputs, like hill sheep farming.', C),
  fact('fm.subsistence', 'farming', 'Farming to feed your own family, with little or nothing left to sell, is called…', 'subsistence farming', ['commercial farming', 'agribusiness', 'arable farming'], 'Commercial farming produces food to sell for profit.', C),
  mcq('fm.humus', 'farming', 'What is humus?', [['Rotted plant and animal matter', true], ['A type of soft volcanic rock', false, 'It is organic matter, not rock.'], ['The layer of rock under the soil', false, 'That is bedrock.'], ['A chemical fertiliser for farms', false, 'It forms naturally.']], 'Humus holds water and nutrients. (The dip is spelled hummus.)'),
  mcq('fm.erosion', 'farming', 'Which practice best protects soil from being washed or blown away?', [['Ploughing along the contours', true], ['Ploughing straight up and down slopes', false, 'Furrows down a slope channel rainwater and soil downhill.'], ['Removing hedges to make big fields', false, 'Hedges break the wind and hold soil.'], ['Leaving fields bare all winter', false, 'Bare soil erodes easily.']], 'In the 1930s Dust Bowl in the USA, bare, over-ploughed soil blew away in huge storms.'),
  mcq('fm.green', 'farming', 'What was the Green Revolution of the 1960s and 1970s?', [['High-yield crops raising food output', true], ['A campaign to plant forests on farmland', false, 'It was about raising crop yields, not forests.'], ['The first organic farming movement', false, 'It relied heavily on fertilisers and pesticides.'], ['A war over farmland in Asia', false, 'It was a change in farming methods.']], 'India became largely self-sufficient in grain, but the costs included water use, chemical pollution and debt for poorer farmers.'),
  mcq('fm.miles', 'farming', 'What are food miles?', [['How far food travels to your plate', true], ['How many miles a farmer drives each year', false, 'It is about the food’s journey.'], ['The size of the farmland used', false, 'It is about transport.'], ['A supermarket loyalty scheme', false, 'It is a measure of transport.']], 'Lower food miles can mean less transport pollution, but not always: tomatoes grown in heated UK greenhouses can have a bigger carbon footprint than ones trucked from sunny Spain.'),
  written('fm.w', 'farming', 'Explain how physical factors affect the type of farming in different parts of the UK.', ['Physical factors: climate (rainfall, temperature), relief, soil', 'An arable example and why it suits the area', 'A pastoral example and why it suits the area', 'A mention of how humans can change things (e.g. machinery, markets)'], 'Physical factors largely decide whether land is used for crops or animals. In East Anglia the land is flat, the soils are fertile and summers are warm and fairly dry, so arable farming of wheat, barley and sugar beet is common and large machines work easily. In upland areas such as Wales and the Lake District, rainfall is high, slopes are steep and soils are thin and acidic, so crops struggle; grass grows well, though, so pastoral farming of sheep and cattle dominates. In between, many lowland farms in the wetter west keep dairy cattle on rich grass. Human factors matter too, such as nearness to markets and subsidies, but climate, relief and soil set the basic pattern.'),

  // --- water and food security
  fact('wf.stress', 'water-food', 'A country is said to face water STRESS when each person has less than about how much water per year?', '1,700 cubic metres', ['17 cubic metres', '17,000 litres', '1 million cubic metres'], 'Below about 1,000 m³ per person a year it is called water scarcity. This is a widely used measure, the Falkenmark indicator.', C),
  mcq('wf.virtual', 'water-food', 'What is “virtual water”?', [['Water used to make what we buy', true], ['Water modelled on computer maps', false, 'It is real water: the water used in production.'], ['Rain that evaporates before landing', false, 'That is not the term.'], ['Bottled water sold abroad', false, 'It is the water hidden in products.']], 'One kilogram of beef needs roughly 15,000 litres of water, mostly to grow the animals’ feed.'),
  mcq('wf.desal', 'water-food', 'Why do Saudi Arabia and the United Arab Emirates rely on desalination?', [['They have little rain and few rivers', true], ['Seawater is healthier than river water', false, 'Seawater must have the salt removed before it can be drunk.'], ['It is the cheapest way to get water', false, 'It uses a lot of energy, so it is expensive.'], ['Their rivers are far too salty', false, 'They have very few rivers at all.']], 'Desalination removes salt from seawater. It is energy-hungry and leaves very salty brine to dispose of.'),
  mcq('wf.euphrates', 'water-food', 'Turkey has built large dams on the Tigris and Euphrates, such as the Atatürk Dam. Why does this worry Syria and Iraq?', [['Less water may reach them downstream', true], ['The dams make the rivers flow backwards', false, 'Rivers cannot flow uphill.'], ['The reservoirs flood their cities', false, 'The reservoirs are in Turkey.'], ['The dams pollute the water with salt', false, 'The main worry is the amount of water, not salt.']], 'Rivers that cross borders can cause tension when the upstream country takes more water.'),
  mcq('wf.nile', 'water-food', 'Why has the Grand Ethiopian Renaissance Dam on the Blue Nile caused tension with Egypt?', [['Egypt fears less Nile water will reach it', true], ['The dam floods land inside Egypt', false, 'It is in Ethiopia, upstream.'], ['Ethiopia wants to stop all fishing', false, 'The dispute is about water flow.'], ['The Nile flows south from Egypt to Ethiopia', false, 'It flows north, from Ethiopia and Uganda towards Egypt.']], 'Ethiopia sees the dam as vital for electricity and development; Egypt sees the Nile as its lifeline.'),
  fact('wf.kielder', 'water-food', 'Which reservoir in Northumberland is the largest artificial lake in the UK by capacity?', 'Kielder Water', ['Lake Windermere', 'Loch Lomond', 'Lough Neagh'], 'Kielder Water opened in 1982 to supply water to north-east England.', { accept: ['kielder', 'kielder water'] }),
  mcq('wf.food', 'water-food', 'What does food security mean?', [['Everyone having enough safe, healthy food', true], ['Guards protecting food warehouses', false, 'It is about access to food, not guards.'], ['A country growing all its own food', false, 'Countries can be food-secure by importing, too.'], ['Every home having a full freezer', false, 'It is about whole populations.']], 'This is the United Nations’ definition. Hundreds of millions of people around the world are still hungry.'),
  mcq('wf.increase', 'water-food', 'Which is a SUSTAINABLE way to increase water supply in a dry region?', [['Rainwater harvesting and fixing leaking pipes', true], ['Pumping groundwater faster than it refills', false, 'That uses up the supply, so it is not sustainable.'], ['Draining wetlands', false, 'That destroys natural water stores.'], ['Watering crops at midday in the sun', false, 'Much of the water would evaporate.']], 'Saving water and collecting rain are cheaper and greener than huge new schemes.'),
  written('wf.w', 'water-food', 'Assess the advantages and disadvantages of building large dams to improve water supply.', ['Advantages: reliable water, irrigation, hydroelectricity, flood control', 'Disadvantages: people displaced, ecosystems, silt, tension with downstream countries', 'At least one named example (e.g. Atatürk Dam, Grand Ethiopian Renaissance Dam, Three Gorges)', 'A judgement: do the benefits outweigh the costs?'], 'Large dams can transform water supply. Their reservoirs store water for dry seasons, supply cities, irrigate farmland and can generate hydroelectric power, as the Grand Ethiopian Renaissance Dam on the Blue Nile is designed to do for Ethiopia. They can also control floods downstream. However, they have serious costs. Building a reservoir floods land, forcing people from their homes and destroying habitats, and the dam traps silt that used to fertilise farmland downstream. They can also cause tension between countries: Egypt fears the Ethiopian dam will reduce the Nile’s flow, and Syria and Iraq worry about Turkey’s dams on the Euphrates. On balance, large dams can bring major benefits, but only if the costs to people, ecosystems and neighbouring countries are shared fairly and planned for.'),

  // --- tourism
  order('tr.butler', 'tourism', 'Put the stages of Butler’s tourism area life cycle in order.', ['Exploration', 'Involvement', 'Development', 'Consolidation', 'Stagnation', 'Decline or rejuvenation'], null, 'A resort is discovered by a few visitors, locals get involved, outside companies build it up, growth slows, it stagnates, and then it either declines or reinvents itself.'),
  mcq('tr.multiplier', 'tourism', 'What is the multiplier effect in tourism?', [['Tourist money is spent again locally', true], ['Tourists telling friends, who then visit', false, 'Word of mouth helps, but the multiplier is about money circulating.'], ['Hotels doubling their prices in summer', false, 'It is about money spreading through the economy.'], ['The number of tourists doubling each year', false, 'It is about how money spreads.']], 'A tourist pays a hotel, the hotel pays its cleaners, they spend wages in local shops, and so on.'),
  mcq('tr.leakage', 'tourism', 'What is “leakage” in tourism?', [['Tourist money flowing abroad', true], ['Sewage leaking from hotels', false, 'It is about money, not sewage.'], ['Tourists losing their luggage', false, 'It is an economic term.'], ['Water leaking from hotel pools', false, 'It is about profits leaving the country.']], 'In some all-inclusive resorts, most of what a tourist pays never reaches local people.'),
  mcq('tr.eco', 'tourism', 'Which is the best example of ecotourism?', [['Small groups with local guides', true], ['A huge new resort built on a coral reef', false, 'That damages the very environment people come to see.'], ['A cruise visiting ten ports in ten days', false, 'Mass cruise tourism has a big environmental footprint.'], ['A safari park built in the desert', false, 'Ecotourism is about protecting nature and benefiting local people.']], 'Ecotourism aims to protect the environment, respect local culture and benefit local people.'),
  mcq('tr.venice', 'tourism', 'Venice has trialled an entry fee for day visitors. Why?', [['Crowds of day-trippers spend little', true], ['To pay for filling in the canals', false, 'The canals are part of what makes Venice special.'], ['Because visitor numbers have collapsed', false, 'It is the opposite: it is overcrowded.'], ['To stop residents leaving their homes', false, 'Residents do not pay the fee.']], 'This is called overtourism. Athens has also introduced timed tickets for the Acropolis to spread the crowds.'),
  mcq('tr.kenya', 'tourism', 'Safaris in Kenya’s Maasai Mara bring money and jobs. Which is a possible NEGATIVE impact?', [['Minibuses crowding the animals', true], ['More money for wildlife protection', false, 'That is a positive impact.'], ['Jobs for local guides', false, 'That is a positive impact.'], ['Visitors learning about Maasai culture', false, 'That can be positive if done respectfully.']], 'Careful management, such as limits on vehicles, helps tourism support conservation.'),
  fact('tr.share', 'tourism', 'An all-inclusive holiday where tourists rarely leave the resort tends to give local businesses…', 'less benefit', ['more benefit', 'the same benefit', 'all the profit'], 'Tourists pay for almost everything in advance, so little money reaches local cafés, guides and shops.', C),
  written('tr.w', 'tourism', 'To what extent is tourism good for a popular destination? Use a named example such as Greece, Venice or Kenya.', ['Economic benefits: jobs, income, the multiplier effect', 'Problems: overcrowding, pollution, leakage, seasonal jobs, rising house prices', 'A named example with specific details', 'How the problems can be managed (e.g. caps, fees, ecotourism)', 'A judgement that answers “to what extent”'], 'Tourism brings large benefits to places like Greece. It creates jobs in hotels, restaurants and transport, earns foreign money, and through the multiplier effect wages are spent again in local shops. It also pays to protect historic sites such as the Acropolis. However, too many visitors can damage the very things they come to see. Popular islands face water shortages in summer, crowded streets and rubbish, and many jobs are seasonal and low-paid. When hotels and cruise lines are foreign-owned, some of the profit leaks out of the country. Places are now managing this: Athens uses timed tickets at the Acropolis and Venice has trialled a fee for day visitors. Overall, tourism is good for a destination to a large extent, but only if numbers are managed so that local people and the environment share the benefits.'),

  // --- deserts and desertification
  mcq('ds.define', 'deserts', 'What makes somewhere a desert?', [['Less than about 250 mm of rain a year', true], ['Being hot all year round', false, 'Antarctica is a desert, and it is freezing.'], ['Being covered in sand dunes', false, 'Only a small part of most deserts is sand dunes; much is rock and gravel.'], ['Having no plants or animals at all', false, 'Many animals live in deserts.']], 'By this definition, the largest desert on Earth is Antarctica.'),
  fact('ds.sahara', 'deserts', 'What is the largest hot desert in the world?', 'the Sahara', ['the Gobi', 'the Kalahari', 'the Atacama'], 'The Sahara covers about 9 million km², roughly the size of the USA.', { accept: ['sahara', 'the sahara desert'] }),
  fact('ds.atacama', 'deserts', 'Which desert in Chile is the driest non-polar place on Earth?', 'the Atacama', ['the Sahara', 'the Namib', 'the Gobi'], 'Some weather stations in the Atacama have recorded almost no rain for years.', { accept: ['atacama'] }),
  fact('ds.sahel', 'deserts', 'What is the name of the semi-arid belt along the southern edge of the Sahara?', 'the Sahel', ['the Savanna Line', 'the Rift', 'the Maghreb'], 'Sahel comes from the Arabic for “shore”: the shore of the great sea of sand.', { accept: ['sahel'] }),
  mcq('ds.causes', 'deserts', 'Which is a HUMAN cause of desertification in the Sahel?', [['Overgrazing by too many animals', true], ['Changes in the Earth’s orbit', false, 'That is natural, and acts over thousands of years.'], ['More rain falling each year', false, 'More rain would help.'], ['Volcanic eruptions nearby', false, 'Not a cause in the Sahel.']], 'Other human causes are over-cultivation and cutting trees for fuelwood; drought and climate change make things worse.'),
  mcq('ds.wall', 'deserts', 'What is the Great Green Wall?', [['A belt of restored land across the Sahel', true], ['A wall to keep sand out of Europe', false, 'It is living vegetation and land restoration, not a wall.'], ['A green wall along China’s deserts', false, 'It is in Africa.'], ['A line of solar farms across Africa', false, 'It is mainly about plants and farming.']], 'Launched in 2007, it aims to restore about 100 million hectares by 2030, though progress has been uneven.'),
  mcq('ds.cactus', 'deserts', 'How is a cactus adapted to the desert?', [['Spines and a thick stem storing water', true], ['Huge thin leaves to catch sunlight', false, 'Big thin leaves would lose too much water.'], ['It needs a little rain every day', false, 'It survives long droughts.'], ['It grows only beside oases', false, 'It grows in dry ground.']], 'Many cacti also have shallow, widespread roots to catch rain quickly.'),
  written('ds.w', 'deserts', 'Explain the causes of desertification in the Sahel, and how people are trying to reduce it.', ['A definition of desertification', 'At least two human causes (overgrazing, over-cultivation, deforestation)', 'Physical causes (drought, climate change)', 'At least two responses (Great Green Wall, stone lines, better farming)'], 'Desertification is when land in dry areas becomes desert-like and loses its ability to grow plants. In the Sahel, a growing population has put pressure on the land: overgrazing by large herds strips vegetation, over-cultivation exhausts the soil, and trees are cut down for fuelwood, so bare soil is blown or washed away. Natural droughts, made worse by climate change, add to the problem. People are fighting back. The Great Green Wall, launched in 2007, aims to restore a belt of land across Africa by planting trees and improving farming. On a smaller scale, farmers build low stone lines along slopes to trap rainwater and soil, and protect young trees growing from old roots. Progress is uneven, but these methods show that desertification can be slowed when local people are involved.'),

  // --- polar regions
  mcq('pl.difference', 'polar', 'What is the main difference between the Arctic and Antarctica?', [['The Arctic is ocean; Antarctica is land', true], ['The Arctic is around the South Pole', false, 'The Arctic is around the North Pole.'], ['Polar bears live on both of them', false, 'Polar bears live only in the Arctic.'], ['They are the same frozen continent', false, 'They are at opposite ends of the Earth.']], 'Penguins live in the south, polar bears in the north: they never meet in the wild.'),
  fact('pl.ice', 'polar', 'Roughly what share of the world’s ice is in Antarctica?', 'about 90%', ['about 10%', 'about 50%', 'about 25%'], 'Antarctica’s ice sheet is up to about 4 km thick and holds most of the world’s fresh water.', C),
  mcq('pl.treaty', 'polar', 'What does the Antarctic Treaty (signed in 1959) do?', [['Keeps it for peaceful science', true], ['Divides it between Britain and Norway', false, 'Territorial claims were frozen, not settled.'], ['Allows oil drilling along the coasts', false, 'Mining and drilling are banned.'], ['Makes Antarctica part of Chile', false, 'No country owns it under the treaty.']], 'The 1991 Madrid Protocol added a ban on mining. It has kept the continent peaceful for over 60 years.'),
  mcq('pl.sea-level', 'polar', 'Why does melting Arctic SEA ice raise sea levels much less than melting ice on Antarctica?', [['Sea ice is already floating', true], ['Arctic ice is mostly snow, not ice', false, 'It is real ice: frozen seawater.'], ['Antarctica is warmer than the Arctic', false, 'Antarctica is colder.'], ['Arctic ice melts more slowly', false, 'The Arctic is an ocean.']], 'Like an ice cube melting in a glass of water: the level hardly changes. Ice sliding off land into the sea does raise it.'),
  mcq('pl.albedo', 'polar', 'As Arctic sea ice melts, the dark ocean absorbs more sunlight. What does this cause?', [['More warming and melting', true], ['Cooling, because the water is cold', false, 'Dark water absorbs more heat than white ice reflects.'], ['No change to the climate at all', false, 'It speeds up warming.'], ['More sea ice forming next year', false, 'It makes the problem worse.']], 'White ice reflects most sunlight; this reflectiveness is called albedo.'),
  mcq('pl.daylight', 'polar', 'Why does the Antarctic have months of continuous daylight in December?', [['The Earth’s tilt', true], ['The Sun is closer in December', false, 'The Earth is actually slightly closer to the Sun in early January, but that is not the reason.'], ['Ice reflects the light all night', false, 'The Sun does not set at all.'], ['It is always daylight there', false, 'In June there are months of darkness.']], 'In June it is the North Pole’s turn for the midnight sun.'),
  fact('pl.vault', 'polar', 'On which Arctic island group is the Global Seed Vault, storing seeds of the world’s crops?', 'Svalbard', ['Greenland', 'Iceland', 'the Falklands'], 'It is dug into a frozen mountain on Svalbard, part of Norway, as a back-up against disasters.', { accept: ['svalbard'] }),
  fact('pl.amundsen', 'polar', 'Which explorer led the first team to reach the South Pole, in December 1911?', 'Roald Amundsen', ['Robert Falcon Scott', 'Ernest Shackleton', 'Edmund Hillary'], 'Amundsen’s Norwegian team used dogs; Scott’s British party arrived about five weeks later and died on the return journey.', { accept: ['amundsen'] }),
  written('pl.w', 'polar', 'Explain why changes in the polar regions matter to people living far away from them.', ['Sea-level rise from melting land ice', 'Feedback loops and faster warming (albedo)', 'Effects on weather, wildlife or shipping', 'A concluding sentence about global connections'], 'Changes in the polar regions affect the whole planet. When ice on land in Antarctica and Greenland melts, it adds water to the oceans and raises sea levels, which threatens low-lying cities and countries such as Bangladesh. As Arctic sea ice shrinks, darker ocean water absorbs more sunlight than white ice reflects, so warming speeds up in a positive feedback loop that affects the global climate. Some scientists think a warmer Arctic may also change the paths of weather systems that reach Europe. There are economic effects too, as new shipping routes and resources open up in the Arctic, which could cause tension between countries. So what happens at the poles does not stay at the poles.'),

  // --- oceans
  fact('oc.share', 'oceans', 'About what percentage of the Earth’s surface is covered by ocean?', 'about 71%', ['about 30%', 'about 50%', 'about 90%'], 'That is why Earth looks blue from space.', C),
  fact('oc.deep', 'oceans', 'What is the deepest known point in the ocean?', 'the Mariana Trench', ['the Puerto Rico Trench', 'the Java Trench', 'the Mid-Atlantic Ridge'], 'It is about 11 km deep, in the western Pacific: deeper than Everest is high.', C),
  mcq('oc.patch', 'oceans', 'What is the Great Pacific Garbage Patch?', [['Plastic gathered by ocean currents', true], ['A solid island of rubbish you can walk on', false, 'Most of it is small pieces and tiny microplastics spread through the water.'], ['A rubbish dump on the Californian coast', false, 'It is in the open ocean.'], ['A huge floating mat of seaweed', false, 'It is plastic pollution.']], 'Circular currents called gyres sweep floating rubbish into the middle, between Hawaii and California.'),
  fact('oc.micro', 'oceans', 'Plastic pieces smaller than 5 mm are called…', 'microplastics', ['nanobeads', 'plankton', 'silt'], 'They come from broken-down bottles, bags and clothing fibres, and are now found from the deep sea to Arctic ice.', { accept: ['microplastic'] }),
  mcq('oc.coral', 'oceans', 'What causes coral bleaching?', [['Warm water makes corals lose algae', true], ['Too much sunlight on cold water', false, 'Heat is the main cause.'], ['Fish eating the coral’s colour', false, 'Some fish nibble coral, but bleaching is caused by heat stress.'], ['Chemical bleach dumped from ships', false, 'It is not chemical bleach.']], 'The Great Barrier Reef has suffered several mass bleaching events since the late 1990s.'),
  mcq('oc.acid', 'oceans', 'Why are the oceans becoming more acidic?', [['They absorb carbon dioxide', true], ['Acid rain from volcanoes only', false, 'Carbon dioxide from burning fossil fuels is the main cause.'], ['Rivers carry acid from farms', false, 'Farm run-off causes other problems; the main cause is carbon dioxide.'], ['Plastic dissolving in seawater', false, 'Plastic does not make seawater acidic.']], 'More acidic water makes it harder for shellfish and corals to build their shells and skeletons.'),
  mcq('oc.cod', 'oceans', 'In 1992 Canada closed the Grand Banks cod fishery. Why?', [['Cod stocks had collapsed', true], ['The cod had all migrated to Africa', false, 'They were fished out.'], ['An oil spill had poisoned them', false, 'It was overfishing, not pollution.'], ['People had stopped eating cod', false, 'Demand stayed high.']], 'About 30,000 people lost their jobs. Decades later, stocks have only partly recovered: a warning about fishing quotas.'),
  written('oc.w', 'oceans', 'Explain two threats to the world’s oceans and suggest how each could be reduced.', ['A first threat explained (e.g. plastic pollution)', 'A realistic way to reduce it', 'A second threat explained (e.g. overfishing, warming, acidification)', 'A realistic way to reduce it'], 'One major threat is plastic pollution. Plastic washes off land and from ships, and ocean currents collect it in gyres such as the Great Pacific Garbage Patch; it breaks into microplastics that animals eat. This could be reduced by cutting single-use plastics, charging for bags and bottles with deposit return schemes, and improving rubbish collection in coastal cities. A second threat is overfishing. When fish are caught faster than they breed, stocks collapse, as cod did on the Grand Banks in 1992. Strict catch quotas, marine protected areas where fishing is banned, and choosing sustainably caught fish can allow stocks to recover.'),

  // --- Africa
  fact('af.count', 'africa', 'How many countries are there in Africa?', '54', ['14', '25', '100'], 'Africa has 54 countries recognised by the United Nations. Nigeria has the most people; Algeria is the biggest by area.'),
  fact('af.kili', 'africa', 'What is the highest mountain in Africa?', 'Kilimanjaro', ['Mount Kenya', 'the Atlas Mountains', 'Table Mountain'], 'Kilimanjaro in Tanzania is about 5,895 m high: a volcano with snow near the Equator.', { accept: ['mount kilimanjaro', 'kilimanjaro'] }),
  fact('af.victoria', 'africa', 'What is the largest lake in Africa?', 'Lake Victoria', ['Lake Chad', 'Lake Malawi', 'Lake Tanganyika'], 'It is shared by Uganda, Kenya and Tanzania, and is a source of the White Nile.', { accept: ['victoria', 'lake victoria'] }),
  mcq('af.young', 'africa', 'Which statement about Africa’s population is TRUE?', [['It is the youngest continent: the average age is under 20', true], ['It is the oldest continent: most people are over 60', false, 'That describes parts of Europe and Japan.'], ['Its population is shrinking fast', false, 'It is growing fast.'], ['Almost nobody lives in cities', false, 'Cities like Lagos, Cairo and Kinshasa have many millions.']], 'A young, fast-growing population could be a huge strength if there are jobs and education.'),
  mcq('af.mpesa', 'africa', 'M-Pesa, launched in Kenya in 2007, is famous for…', [['Sending money by mobile phone', true], ['Being Africa’s first railway', false, 'It is a mobile money service.'], ['Being Kenya’s biggest safari park', false, 'It is mobile banking.'], ['Being a famous Nairobi football club', false, 'It is mobile money.']], 'It reached people without bank accounts and is copied around the world.'),
  mcq('af.rift', 'africa', 'What is the Great Rift Valley?', [['East African land pulling apart', true], ['A long river valley in West Africa', false, 'It is a valley system, mainly in East Africa.'], ['A canal dug across the continent', false, 'It formed naturally.'], ['A desert in southern Africa', false, 'It runs through Ethiopia, Kenya and Tanzania.']], 'Some of the oldest human fossils have been found along it.'),
  mcq('af.stereotype', 'africa', 'Which is a MISLEADING stereotype about Africa?', [['That it is one poor country', true], ['That it has 54 countries', false, 'That is a fact.'], ['That it has huge, growing cities', false, 'Lagos, Cairo, Kinshasa and Johannesburg are huge.'], ['That it has deserts and rainforests', false, 'All true: it is hugely varied.']], 'Africa has some of the world’s fastest-growing economies alongside very poor regions: like any continent, it is varied.'),
  fact('af.languages', 'africa', 'Roughly how many languages are spoken in Africa?', 'over a thousand', ['about forty', 'about two hundred', 'about fifty-four'], 'Estimates range from about 1,500 to over 2,000, including Swahili, Hausa, Yoruba, Amharic, Zulu and Arabic.', C),
  written('af.w', 'africa', 'Using examples, explain why it is misleading to describe Africa as if it were one place.', ['The size and number of countries', 'Physical variety (deserts, rainforest, mountains, rift valley)', 'Economic variety, with at least one example of growth or innovation', 'Cultural variety (languages, religions)', 'A conclusion'], 'Describing Africa as one place is misleading because it is a vast and varied continent of 54 countries. Physically it ranges from the Sahara, the largest hot desert, to the rainforests of the Congo basin and the snow-capped volcano of Kilimanjaro. Economies vary too: some countries remain very poor, but others are growing fast, and Kenya’s M-Pesa mobile money service, launched in 2007, was a world first. Culturally there are well over a thousand languages and many religions. Lagos and Johannesburg are huge modern cities, while millions still farm the land. Treating Africa as one place hides this variety and repeats stereotypes about poverty and conflict that do not fit most people’s lives.'),

  // --- Nigeria
  fact('ng.pop', 'nigeria', 'Nigeria is the African country with the most…', 'people', ['land area', 'snow', 'coastline'], 'With over 200 million people, Nigeria has the largest population in Africa.', C),
  mcq('ng.nee', 'nigeria', 'Nigeria is often described as a newly emerging economy (NEE). What does that mean?', [['Its economy is growing and changing fast', true], ['It has only just become independent', false, 'It became independent from Britain in 1960.'], ['It is the richest country in Africa per person', false, 'It has one of Africa’s largest economies in total, but income per person is low.'], ['Its economy depends only on farming', false, 'Industry and services are growing fast.']], 'Other NEEs include India, Brazil and China.'),
  mcq('ng.oil', 'nigeria', 'Which is a PROBLEM linked to oil in the Niger Delta?', [['Oil spills polluting rivers and farmland', true], ['Oil providing much of the government’s income', false, 'That is a benefit, though it has also encouraged corruption.'], ['New jobs in the oil industry', false, 'That is a benefit, though many jobs go to skilled outsiders.'], ['Cheaper fuel for local people', false, 'That is not the main problem.']], 'Oil makes up most of Nigeria’s exports, but relying on one product is risky when world prices fall.'),
  fact('ng.nollywood', 'nigeria', 'What is the nickname of Nigeria’s huge film industry?', 'Nollywood', ['Bollywood', 'Lagowood', 'Afrowood'], 'By number of films made each year, Nollywood is one of the largest film industries in the world.', { accept: ['nollywood'] }),
  fact('ng.indep', 'nigeria', 'In which year did Nigeria become independent from Britain?', '1960', ['1914', '1947', '1990'], 'Britain had joined the north and south together as one colony in 1914.'),
  mcq('ng.lagos', 'nigeria', 'Why has Lagos grown so fast?', [['Migration for jobs and a high birth rate', true], ['It is the capital, so the government moved everyone there', false, 'Abuja is the capital.'], ['It has the coolest climate in Nigeria', false, 'It is hot and humid.'], ['Its population is mostly elderly people', false, 'Rural–urban migration is a key reason.']], 'Lagos is one of Africa’s largest cities, with many millions of people.'),
  fact('ng.groups', 'nigeria', 'Nigeria’s three largest ethnic groups are the Hausa-Fulani, the Yoruba and the…', 'Igbo', ['Zulu', 'Maasai', 'Ashanti'], 'Nigeria has hundreds of ethnic groups and languages; English is the official language.', { accept: ['igbo', 'ibo'] }),
  written('ng.w', 'nigeria', 'Assess how far oil has helped Nigeria to develop.', ['How oil has helped (income, exports, jobs, infrastructure)', 'Problems: pollution in the Niger Delta, reliance on one export, inequality, corruption', 'Evidence of diversification (e.g. Nollywood, services, farming)', 'A judgement: “how far”'], 'Oil has helped Nigeria’s development in some ways. It brings in most of the country’s export earnings and a large share of government income, which has paid for roads, schools and the new capital, Abuja, and it has created jobs and attracted foreign investment. However, the benefits have been uneven. Oil spills in the Niger Delta have polluted farmland, rivers and mangroves, harming the fishing and farming that local people depend on. Relying on one export makes the economy vulnerable when world oil prices fall, and oil wealth has been linked to corruption and inequality. Nigeria is now diversifying into services, telecommunications, farming and film, through Nollywood. Overall, oil has helped Nigeria develop to some extent, but it has not shared its wealth fairly, and other industries will be needed for lasting development.'),

  // --- China
  mcq('cn.onechild', 'china', 'China’s one-child policy ran from about 1980 to 2015. What is one long-term effect?', [['An ageing population', true], ['A sudden population explosion', false, 'It slowed growth sharply.'], ['More girls than boys being born', false, 'The opposite: a preference for sons led to more boys.'], ['No lasting effect at all', false, 'Its effects will last for decades.']], 'China now encourages families to have up to three children, but many choose to have one or none.'),
  mcq('cn.gorges', 'china', 'What is a benefit of the Three Gorges Dam on the Yangtze River?', [['Huge amounts of hydroelectric power', true], ['Nobody had to move home for it', false, 'More than a million people were relocated.'], ['More silt now reaches the sea', false, 'It traps silt behind the dam.'], ['It made the river safe to swim in', false, 'It is one of the largest power stations in the world.']], 'Costs included lost farmland, flooded towns and historic sites, and changes to river ecosystems.'),
  mcq('cn.shenzhen', 'china', 'Shenzhen grew from a small town to a city of over 10 million people in about 40 years. Why?', [['It became a Special Economic Zone', true], ['Gold was discovered there in 1980', false, 'It was government economic policy.'], ['It became China’s new capital', false, 'Beijing is the capital.'], ['It has a cool mountain climate', false, 'It is in the warm south, next to Hong Kong.']], 'Special Economic Zones offered low taxes and cheap labour to foreign investors.'),
  mcq('cn.emit', 'china', 'Which statement about China and carbon dioxide is correct?', [['It emits most in total, but not per person', true], ['It emits almost none at all', false, 'It burns a great deal of coal.'], ['It emits the most per person in the world', false, 'Some smaller, richer countries emit more per person.'], ['It has almost no renewable energy', false, 'It builds more solar and wind power than any other country.']], 'Total and per-person figures tell different stories: both matter.'),
  fact('cn.yellow', 'china', 'Which Chinese river has been called “China’s Sorrow” because of its deadly floods?', 'the Yellow River', ['the Yangtze River', 'the Mekong River', 'the Pearl River'], 'Its yellow silt raises the riverbed, so floods can break through embankments across the flat plain.', C),
  mcq('cn.hukou', 'china', 'What is China’s hukou system?', [['A household registration system', true], ['A high-speed railway network', false, 'It is a registration system, not a railway.'], ['A national pension scheme', false, 'It records where a household is registered to live.'], ['A system of national parks', false, 'It is about where people are registered to live.']], 'Millions of migrant workers built China’s cities without full rights to schools or healthcare there, though rules have been relaxed.'),
  fact('cn.belt', 'china', 'China’s programme, begun in 2013, to fund ports, railways and roads in dozens of countries is called…', 'the Belt and Road Initiative', ['the Great Leap Forward', 'the Silk Road Act', 'the Marshall Plan'], 'It is named after the ancient Silk Road trade routes. Critics worry about some countries’ debts.', C),
  written('cn.w', 'china', 'Assess the advantages and disadvantages of the Three Gorges Dam.', ['What and where it is', 'Advantages: hydroelectric power, flood control, river navigation', 'Disadvantages: people relocated, lost heritage and farmland, silt, ecosystems, landslides', 'A balanced judgement'], 'The Three Gorges Dam on the Yangtze River in China is one of the largest power stations in the world. Its main advantage is clean hydroelectric power, which reduces China’s reliance on coal and cuts air pollution. It also helps control the floods that have killed many thousands of people along the Yangtze, and the reservoir lets large ships travel further inland. However, the costs were huge. More than a million people were moved from their homes, and towns, farmland and archaeological sites were flooded. The dam traps silt, so less reaches the farmland and delta downstream, and the reservoir has been linked to landslides and harm to river wildlife. On balance, the dam has brought major national benefits, but they came at a heavy cost to the people and ecosystems of the valley.'),

  // --- India
  mcq('in.monsoon', 'india', 'What is the Indian monsoon?', [['A seasonal wind bringing summer rain', true], ['A type of tropical earthquake', false, 'It is a seasonal wind and rain pattern.'], ['A winter snowstorm in the Himalayas', false, 'It brings summer rain.'], ['A dry wind from the Thar Desert', false, 'It is a weather pattern.']], 'The land heats faster than the sea, drawing in moist ocean air that rises and drops its rain.'),
  mcq('in.depend', 'india', 'Why does the monsoon matter so much to India?', [['Most farms depend on its rain', true], ['It mainly affects tourists', false, 'It affects hundreds of millions of farmers.'], ['It brings snow for the rivers', false, 'Himalayan snowmelt feeds rivers, but the monsoon brings rain.'], ['It has little effect on food', false, 'Food prices rise when it fails.']], 'Much of the year’s rain falls in a few months, so storing water matters.'),
  fact('in.ganges', 'india', 'Which river is sacred to Hindus and flows from the Himalayas across northern India?', 'the Ganges', ['the Indus River', 'the Brahmaputra', 'the Godavari'], 'Millions bathe in it at Varanasi; it is also heavily polluted, and big clean-up schemes are under way.', C),
  fact('in.bengaluru', 'india', 'Which Indian city is known as the centre of its IT industry, sometimes called “India’s Silicon Valley”?', 'Bengaluru', ['Mumbai', 'Kolkata', 'Chennai'], 'Many global technology companies have offices there.', C),
  mcq('in.wet', 'india', 'Some of the wettest places on Earth are in north-east India, near Mawsynram and Cherrapunji. Why?', [['Monsoon winds rise over the hills', true], ['They lie in a low, sheltered basin', false, 'They are high in the hills.'], ['Warm volcanic ground heats the air', false, 'It is relief rainfall.'], ['They are close to the Equator', false, 'They are in the wettest part of India.']], 'Some years they get over 11 metres of rain.'),
  mcq('in.moon', 'india', 'In 2023 India’s Chandrayaan-3 mission became the first to land near the Moon’s…', [['south pole', true], ['far side for the first time ever', false, 'China landed on the far side first, in 2019.'], ['Sea of Tranquillity', false, 'That was where Apollo 11 landed in 1969.'], ['north pole', false, 'It landed near the south pole.']], 'Scientists want to study ice that may be hidden in craters there.'),
  written('in.w', 'india', 'Explain how India’s physical geography affects the lives of people who live there.', ['The monsoon and farming', 'Rivers such as the Ganges (water, farming, religion, flooding)', 'Mountains (the Himalayas: water source, barrier, hazards)', 'At least one specific example or fact'], 'India’s physical geography shapes daily life. The monsoon brings most of the year’s rain between about June and September, and hundreds of millions of farmers depend on it: a weak monsoon can mean poor harvests and higher food prices, while a very strong one can cause floods. The great rivers, especially the Ganges, flowing from the Himalayas, provide water for farming and cities and are sacred to Hindus, though they can also flood. The Himalayas themselves are a source of water from melting snow and glaciers, a barrier to the north, and a hazard area for earthquakes and landslides. In the north-east, relief rainfall makes places like Mawsynram among the wettest on Earth.'),

  // --- Brazil and the Amazon
  mcq('bz.share', 'brazil', 'About how much of the Amazon rainforest is in Brazil?', [['About 60%', true], ['All of it', false, 'It spreads across nine countries, including Peru and Colombia.'], ['About 5%', false, 'Brazil has the largest share by far.'], ['None', false, 'Brazil has most of it.']], 'The Amazon covers about 5.5 million km².'),
  mcq('bz.lungs', 'brazil', 'The Amazon is often called “the lungs of the planet”. Why do scientists say this is misleading?', [['It uses most of the oxygen it makes', true], ['The Amazon makes no oxygen at all', false, 'It makes plenty, but uses most of it itself.'], ['It breathes in oxygen at night only', false, 'It is a metaphor.'], ['It produces more carbon than it stores', false, 'It is the largest rainforest on Earth.']], 'Burning it releases stored carbon, which speeds up climate change.'),
  mcq('bz.road', 'brazil', 'How did the Trans-Amazonian Highway, begun in the 1970s, speed up deforestation?', [['It opened the forest to settlers', true], ['Its traffic pollution killed the trees', false, 'It was the access it gave, not the cars.'], ['It flooded large areas of the forest', false, 'Roads do not flood forests; dams can.'], ['It had no effect on the forest', false, 'Deforestation often follows new roads.']], 'Satellite images show a “fishbone” pattern of clearing along side roads.'),
  fact('bz.soy', 'brazil', 'Apart from cattle ranching, which crop, grown largely for animal feed, has driven forest clearing in Brazil?', 'soya', ['coffee', 'tea', 'cotton'], 'Much of it is exported to feed pigs and chickens in China and Europe.', { accept: ['soy', 'soybeans', 'soya beans'] }),
  mcq('bz.indigenous', 'brazil', 'Why do many scientists argue that protecting indigenous peoples’ land rights helps protect the rainforest?', [['Their forest is cleared far less', true], ['Indigenous peoples do not live in the Amazon', false, 'Hundreds of indigenous groups live there.'], ['It is cheaper to cut the forest down', false, 'The question is about protection.'], ['Indigenous people own all the land already', false, 'Most depend on the forest.']], 'Satellite maps show forest boundaries that match territory boundaries.'),
  mcq('bz.manaus', 'brazil', 'Why does the city of Manaus, in the middle of the Amazon, have so many factories?', [['It is a tax-free trade zone', true], ['It is a big port on the coast', false, 'It is about 1,500 km inland.'], ['It is Brazil’s capital city', false, 'Brasília is the capital.'], ['Its factories need rainforest wood', false, 'It is about tax incentives.']], 'Goods such as motorbikes and electronics are made there and shipped down the Amazon.'),
  fact('bz.river', 'brazil', 'The Amazon river carries more water than any other river. What is this volume of flowing water called?', 'discharge', ['erosion', 'velocity', 'precipitation'], 'Its discharge is greater than the next several largest rivers combined.', { accept: ['its discharge'] }),
  written('bz.w', 'brazil', '“Protecting the Amazon is the responsibility of the whole world, not just Brazil.” How far do you agree?', ['Why the Amazon matters globally (carbon, climate, biodiversity, rainfall)', 'Brazil’s point of view: development, jobs, sovereignty, poverty', 'Ideas for shared responsibility (funding, buying choices, supply chains)', 'A clear judgement'], 'I largely agree, because the Amazon matters to everyone. It stores enormous amounts of carbon, so clearing and burning it speeds up climate change worldwide; it recycles rainfall that farms far beyond the forest depend on; and it holds a huge share of the world’s species. However, it is mostly Brazilian territory, and Brazil has the right to make its own decisions and to develop. Farming, mining and roads bring jobs and income, and many Brazilians are poor. So responsibility should be shared. Richer countries can fund protection, for example by paying to keep forests standing, and consumers and companies can refuse beef and soya grown on newly cleared land. Brazil, in turn, can enforce its laws and protect indigenous territories. The world should share the cost, but Brazil must lead.'),

  // --- the EU and borders
  fact('eu.members', 'eu', 'How many member countries has the European Union had since the UK left in 2020?', '27', ['15', '28', '50'], 'The UK left on 31 January 2020, four years after the 2016 referendum.'),
  mcq('eu.three', 'eu', 'Which statement is TRUE?', [['Not every EU country uses the euro', true], ['Every EU country uses the euro', false, 'Several, such as Poland, Sweden and Denmark, still use their own currencies.'], ['Schengen and the EU are the same group', false, 'Some non-EU countries such as Norway and Switzerland are in Schengen.'], ['The UK is still in the Schengen area', false, 'The UK never joined Schengen, and has now left the EU.']], 'The euro is shared by 20 EU countries; Schengen removes routine passport checks at most internal borders.'),
  fact('eu.schengen', 'eu', 'The agreement that removed routine passport checks between most European countries is named after a village in…', 'Luxembourg', ['France', 'Belgium', 'Germany'], 'Schengen is a small village where the agreement was signed in 1985, near where Luxembourg, France and Germany meet.', C),
  fact('eu.rome', 'eu', 'The European Economic Community, which grew into the EU, was set up by the Treaty of Rome in which year?', '1957', ['1918', '1945', '1992'], 'Six countries started it, partly to make another war between France and Germany impossible.'),
  mcq('eu.movement', 'eu', 'What does “freedom of movement” in the EU mean?', [['EU citizens can live and work in any EU country', true], ['Anyone in the world can move to the EU', false, 'It applies to EU citizens.'], ['Goods can cross borders with no taxes', false, 'That is the single market for goods; free movement is about people.'], ['Countries can move their borders freely', false, 'It is about people.']], 'UK citizens lost this right in the EU when Brexit took effect.'),
  mcq('eu.ireland', 'eu', 'Why was the border between Northern Ireland and the Republic of Ireland such a difficult issue in the Brexit talks?', [['Nobody wanted border checkpoints again', true], ['There is no border there at all', false, 'There is a border, but it has been open with no checks.'], ['Ireland wanted to leave the EU too', false, 'Ireland stayed in the EU.'], ['It is only a short sea border', false, 'It is a land border about 500 km long.']], 'Checks on some goods were moved to ports between Great Britain and Northern Ireland instead.'),
  fact('eu.capital', 'eu', 'Which city is home to the European Commission, the EU’s main executive body?', 'Brussels', ['Strasbourg', 'Paris', 'Luxembourg'], 'The European Parliament meets in both Strasbourg and Brussels.', { accept: ['brussels'] }),
  written('eu.w', 'eu', 'Explain how borders can affect people’s lives, using examples from Europe.', ['What borders can control (people, goods, money)', 'An example of open borders (Schengen, freedom of movement)', 'An example where borders became harder (Brexit) or were sensitive (Irish border)', 'Effects on trade, work, travel or identity'], 'Borders control how people, goods and money move, so they shape everyday life. Inside the Schengen area, most European countries have no routine passport checks, so people can commute, shop and travel across borders easily, and freedom of movement lets EU citizens live and work in any member country. When the UK left the EU in 2020, borders became harder again: British citizens now need to meet extra rules to work in the EU, and businesses face paperwork and checks when trading. The border in Ireland shows how sensitive borders can be: an open border helped support peace after the 1998 Good Friday Agreement, so finding a way to avoid checkpoints was a major issue in the Brexit talks.'),

  // --- regeneration
  mcq('rg.brownfield', 'regeneration', 'What is a brownfield site?', [['Land that has been built on before', true], ['A field used for brown crops', false, 'It is previously developed land.'], ['Countryside never built on', false, 'That is a greenfield site.'], ['A polluted river or canal bank', false, 'It is about land.']], 'Building on brownfield land protects the countryside, though cleaning up old industrial land can be expensive.'),
  mcq('rg.docklands', 'regeneration', 'Why did London’s Docklands decline in the 1960s and 1970s?', [['Big container ships could not reach them', true], ['The River Thames silted up', false, 'It was about bigger ships, not silt.'], ['A great flood destroyed them in 1953', false, 'They closed as trade moved.'], ['They were too far from central London', false, 'They were in the heart of East London.']], 'Thousands of jobs were lost and the area became run-down.'),
  mcq('rg.canary', 'regeneration', 'Which was a criticism of how London’s Docklands were regenerated from the 1980s?', [['New jobs went mainly to commuters', true], ['Almost nothing new was built', false, 'Canary Wharf, the DLR and City Airport were built.'], ['It was turned back into farmland', false, 'It became offices and homes.'], ['The new homes were too cheap', false, 'Prices rose sharply.']], 'This is called gentrification. Regeneration helps an area, but not always the people who lived there.'),
  fact('rg.olympic', 'regeneration', 'Which part of East London was regenerated for the 2012 Olympic and Paralympic Games?', 'Stratford', ['Kensington', 'Wembley', 'Wimbledon'], 'Polluted former industrial land became the Queen Elizabeth Olympic Park, with new homes, parkland and transport.', { accept: ['stratford'] }),
  mcq('rg.greenbelt', 'regeneration', 'What is a green belt?', [['Protected countryside around a city', true], ['A row of trees along a motorway', false, 'It is much bigger: a protected zone around a city.'], ['A recycling scheme for green waste', false, 'It is planning land.'], ['Parks inside the city centre', false, 'City parks are green space, but the green belt surrounds the city.']], 'Green belts stop cities sprawling, but they also make it harder to build enough homes.'),
  mcq('rg.counter', 'regeneration', 'Counter-urbanisation is when…', [['people leave cities for the countryside', true], ['people move from the countryside into cities', false, 'That is urbanisation.'], ['old city buildings are knocked down', false, 'It is about people moving.'], ['people move back into city centres', false, 'That is re-urbanisation.']], 'Better transport and working from home have helped some people move further out.'),
  fact('rg.dlr', 'regeneration', 'Which light railway opened in 1987 to link the regenerated Docklands to the City of London?', 'the Docklands Light Railway', ['the Elizabeth line', 'the Jubilee line extension', 'the London Overground'], 'Its driverless trains were part of making Docklands attractive to businesses.', C),
  written('rg.w', 'regeneration', 'To what extent has the regeneration of an urban area in the UK benefited local people? Use a named example.', ['Why the area needed regenerating', 'What was done (named projects)', 'Benefits: jobs, transport, environment, homes', 'Problems: gentrification, house prices, who got the jobs', 'A judgement'], 'London’s Docklands declined in the 1960s and 1970s when container ships moved to deeper ports, leaving derelict docks and high unemployment. From 1981 a development corporation attracted investment: offices at Canary Wharf, the Docklands Light Railway, City Airport and thousands of new homes. This brought tens of thousands of jobs and transformed the environment. However, many of the new jobs were in finance and went to skilled commuters rather than former dockworkers, and rising house prices pushed some local families out, an example of gentrification. Later projects, such as the 2012 Olympic Park at Stratford, tried harder to include affordable housing and local training. Overall, regeneration benefited the area a great deal, but local people only partly shared in those benefits.'),

  // --- fieldwork and GIS
  order('fw.enquiry', 'fieldwork', 'Put the stages of a geographical enquiry in order.', ['Ask a question or hypothesis', 'Collect data', 'Present the data', 'Analyse the results', 'Draw a conclusion', 'Evaluate how reliable it was'], null, 'Every GCSE fieldwork project follows these steps, and examiners love the last one.'),
  mcq('fw.systematic', 'fieldwork', 'Measuring a river’s depth every 50 cm across its width is an example of which kind of sampling?', [['Systematic sampling', true], ['Random sampling', false, 'Random sampling would choose points by chance, e.g. with random numbers.'], ['Stratified sampling', false, 'Stratified sampling takes samples in proportion to sub-groups.'], ['No sampling at all', false, 'It is a sample of points, not every point.']], 'Systematic: at regular intervals. Random: chosen by chance. Stratified: in proportion to groups.'),
  mcq('fw.stratified', 'fieldwork', 'A village is 70% houses and 30% flats. You interview 70 people from houses and 30 from flats. This is…', [['stratified sampling', true], ['random sampling', false, 'You chose numbers to match the groups.'], ['systematic sampling', false, 'You did not pick every nth home.'], ['secondary data', false, 'You collected it yourself: primary data.']], 'Stratified samples make sure every group is fairly represented.'),
  mcq('fw.primary', 'fieldwork', 'Which of these is PRIMARY data?', [['A traffic count you did yourself', true], ['Census statistics from a government website', false, 'Data collected by someone else is secondary.'], ['A newspaper article', false, 'Secondary.'], ['A textbook map', false, 'Secondary.']], 'Primary data: you collected it. Secondary data: someone else did.'),
  fact('fw.qual', 'fieldwork', 'Interview answers, sketches and photographs are examples of which type of data?', 'qualitative data', ['quantitative data', 'secondary data', 'continuous data'], 'Qualitative data is descriptive; quantitative data is numbers you can measure or count.', C),
  mcq('fw.gis', 'fieldwork', 'What is a GIS?', [['Software that layers data on maps', true], ['A satellite navigation compass', false, 'It is software.'], ['A satellite that takes photos', false, 'Satellites can provide data, but a GIS is the system that maps and analyses it.'], ['A kit for testing soil samples', false, 'It is about digital maps.']], 'For example, layering flood risk, housing and school locations helps planners decide where to build.'),
  mcq('fw.remote', 'fieldwork', 'Why are satellite images useful for studying the Amazon?', [['They show clearing over huge areas', true], ['They count every individual animal', false, 'They are not that detailed.'], ['They replace the need for fieldwork', false, 'Ground checks are still needed.'], ['They see clearly through thick cloud', false, 'Most images need daylight, though radar can see through cloud.']], 'Collecting data from a distance like this is called remote sensing.'),
  mcq('fw.reliable', 'fieldwork', 'How could you make a traffic survey more reliable?', [['Repeat the counts and average them', true], ['Count for one minute at rush hour', false, 'A tiny sample is unreliable.'], ['Estimate the numbers by eye', false, 'Data must be measured.'], ['Count only the cars, not lorries', false, 'That would give a biased sample.']], 'Bigger, repeated samples reduce the effect of unusual results.'),
  written('fw.w', 'fieldwork', 'Plan a fieldwork enquiry to test this hypothesis: “The environmental quality of a town gets better further from the centre.”', ['How you would sample sites (e.g. systematic along a transect)', 'What you would measure (e.g. an environmental quality survey, litter, noise, traffic)', 'At least one source of secondary data', 'How you would present and analyse the results', 'One way to make it reliable, and one risk to manage'], 'I would draw a transect from the town centre outwards and use systematic sampling, stopping every 200 metres. At each site I would complete an environmental quality survey, scoring things like litter, noise, traffic and green space from −2 to +2, and take a photograph. I would also count the number of cars passing in two minutes. For secondary data I would use crime or house-price maps from the internet. I would present the scores on a line graph against distance from the centre and test the pattern with a scatter graph. To make it reliable, two people would score each site and I would repeat it on a second day. I would carry out a risk assessment, for example for busy roads, and work in a group.'),

  // --- sustainability
  fact('su.goals', 'sustainability', 'How many Sustainable Development Goals did the United Nations agree in 2015?', '17', ['8', '10', '50'], 'They run to 2030 and include ending poverty, zero hunger, clean water, climate action and quality education.'),
  mcq('su.define', 'sustainability', 'Which is the best definition of sustainable development?', [['Meeting today’s needs without harming the future', true], ['Making as much money as fast as possible', false, 'That may not be sustainable.'], ['Stopping all new building and industry', false, 'Sustainability is about how we develop, not stopping.'], ['Using only solar and wind power', false, 'Energy is one part, but the idea is much wider.']], 'This definition comes from the 1987 Brundtland Report.'),
  fact('su.mdg', 'sustainability', 'The Sustainable Development Goals replaced which earlier set of eight goals (2000–2015)?', 'the Millennium Goals', ['the Paris Agreement', 'the Kyoto Protocol', 'the Rio Earth Summit'], 'The Millennium Goals halved extreme poverty, but missed many targets.', C),
  mcq('su.three', 'sustainability', 'Sustainability is often described as having three parts. What are they?', [['Environmental, social and economic', true], ['Water, food and clean air', false, 'Those are resources, not the three parts.'], ['Political, cultural and technological', false, 'Those are other ways to analyse an issue; the three pillars are environmental, social and economic.'], ['Local, national and global', false, 'Those are scales.']], 'A truly sustainable project protects the environment, treats people fairly and pays its way.'),
  mcq('su.circular', 'sustainability', 'What is a circular economy?', [['Products reused and recycled, not binned', true], ['Money circulating around a town', false, 'That is the multiplier effect; a circular economy is about loops of materials.'], ['Trading only with neighbouring countries', false, 'It is about materials, not trade partners.'], ['Using only renewable energy sources', false, 'It is about resources.']], 'It replaces “take, make, throw away” with loops of reuse.'),
  mcq('su.fairtrade', 'sustainability', 'How does the Fairtrade mark aim to help farmers in poorer countries?', [['It guarantees a minimum price', true], ['It removes import taxes', false, 'Shoppers still pay.'], ['It bans exports of raw crops', false, 'It supports exports on fairer terms.'], ['It only applies to UK farmers', false, 'It is for producers in poorer countries.']], 'Coffee, cocoa and bananas are common Fairtrade products.'),
  fact('su.footprint', 'sustainability', 'The total amount of greenhouse gases caused by a person, product or activity is its…', 'carbon footprint', ['water table', 'albedo', 'GNI'], 'Flying, heating and diet make up much of a typical UK carbon footprint.', { accept: ['its carbon footprint'] }),
  written('su.w', 'sustainability', 'Using one example, explain how a project can be environmentally, socially and economically sustainable.', ['Name and describe a project (e.g. an eco-town, a rainforest ecotourism lodge, a solar scheme)', 'How it is environmentally sustainable', 'How it is socially sustainable', 'How it is economically sustainable', 'Any weakness'], 'An ecotourism lodge in the rainforest, run with a local community, can be sustainable in all three ways. Environmentally, it uses solar power, collects rainwater and treats its waste, and visitor numbers are limited so the forest and wildlife are protected; some profits fund rangers. Socially, local people are employed as guides and cooks, their culture is respected, and they have a say in decisions. Economically, it earns steady income that stays in the community instead of leaking to foreign companies, which gives people a reason to keep the forest standing rather than sell it for logging. A weakness is that guests still fly long distances, so its carbon footprint is not zero.'),

  // --- world places, part 2
  ...PLACES.flatMap(([id, name, capital, wrong, note, acceptName, acceptCap, cont]) => [
    { id: `geography.m.pl.${id.toLowerCase()}`, topic: 'geography.places-2', kind: 'mapfact', map: 'world', layer: 'countries', feature: id, zoom: ZOOM[cont], answer: name, accept: acceptName, choosePrompt: 'Which country is highlighted?', explain: `This is ${name}. ${note}` },
    fact(`plc.${id.toLowerCase()}`, 'places-2', `What is the capital of ${name}?`, capital, wrong, `The capital of ${name} is ${capital}. ${note}`, {
      map: 'world', layer: 'countries', feature: id, zoom: ZOOM[cont], fill: true, accept: acceptCap,
      learn: `The capital of **${name}** is **${capital}**. ${note}`,
    }),
  ]),

  // --- decisions (GCSE taster)
  order('dc.steps', 'decisions', 'Put the steps of a good decision-making answer in order.', ['Identify the options', 'Identify the stakeholders and their views', 'Weigh the costs and benefits of each option', 'Choose one option', 'Justify it and say why you rejected the others'], null, 'GCSE mark schemes reward a clear choice, backed by evidence, that also explains the drawbacks.'),
  mcq('dc.stakeholder', 'decisions', 'In geography, what is a stakeholder?', [['Anyone affected by a decision', true], ['Someone who owns shares in a company', false, 'It means someone with a “stake” (an interest) in an issue.'], ['Only the government and council', false, 'Residents, businesses, charities and others are stakeholders too.'], ['Only the people who pay for it', false, 'It is about people with an interest.']], 'For a new coastal defence: residents, farmers, the council, tourists and wildlife groups.'),
  mcq('dc.coast', 'decisions', 'A council can protect only one of these with its coastal defence budget. Which choice is easiest to justify on cost–benefit grounds?', [['A town of 10,000 people', true], ['An empty field worth very little', false, 'The cost would far outweigh what is protected.'], ['A single disused farm barn', false, 'Very little would be gained.'], ['A cliff with nothing on it', false, 'Nothing valuable is at risk.']], 'Cost–benefit analysis compares what protection costs with the value of what it saves. It is not the only factor: fairness and the environment matter too.'),
  mcq('dc.sustain', 'decisions', 'Which phrase from an answer shows the strongest evaluation?', [['“Although it costs more, the dam is better because…”', true], ['“The dam is good and the other options are bad.”', false, 'There is no reason or comparison.'], ['“I like option B best because it is nice.”', false, 'A choice needs justifying with evidence.'], ['“All the options have good and bad points.”', false, 'True, but it does not weigh them or reach a judgement.']], 'Words like “although”, “however” and “on balance” show you are weighing the options.'),
  mcq('dc.conflict', 'decisions', 'A new holiday resort is planned on an unspoilt Greek island. Which stakeholders are most likely to DISAGREE?', [['A hotel developer and a local conservation group', true], ['A hotel developer and a construction company', false, 'Both would probably welcome the project.'], ['Two conservation charities', false, 'They would probably agree.'], ['Tourists and the travel company selling holidays there', false, 'Both might welcome it.']], 'Identifying conflicting views is the first step to a fair decision.'),
  written('dc.w', 'decisions', 'A coastal town is eroding. The options are: (A) build a sea wall, (B) put rock armour at the base of the cliffs, (C) do nothing and help people move away (managed retreat). Choose one option and justify your choice.', ['State your choice clearly', 'Use costs and benefits of your option', 'Consider at least two stakeholders', 'Explain why you rejected the other options', 'Mention sustainability'], 'I would choose option B, rock armour. It is much cheaper than a sea wall and it absorbs wave energy, so the cliffs erode more slowly, protecting homes and businesses for several decades. Residents and local businesses would welcome this, although some tourists might find the rocks less attractive than a sandy beach. A sea wall would protect the town more strongly, but it is very expensive, reflects wave energy that can scour away the beach, and may simply move the problem along the coast. Managed retreat is the most sustainable in the long term, but it would mean many families losing their homes now, which is unfair while cheaper protection is still possible. Rock armour therefore balances cost, fairness and the environment best, while the council plans for retreat in the future.'),

  // --- urban models (GCSE taster)
  order('um.burgess', 'urban-models', 'Put the zones of the Burgess model in order, from the centre outwards.', ['Central business district (CBD)', 'Inner city (factories and older terraced housing)', 'Inner suburbs', 'Outer suburbs', 'Rural–urban fringe'], null, 'Ernest Burgess described these rings around Chicago in the 1920s. Real cities fit it only roughly.'),
  mcq('um.cbd', 'urban-models', 'Why are buildings in the central business district (CBD) usually tall?', [['Land there is the most expensive', true], ['The ground there is the firmest', false, 'It is about land value.'], ['Tall buildings are required by law', false, 'It is about cost.'], ['The tall buildings were built first', false, 'Lifts help with that.']], 'Shops and offices compete for the most accessible land, which drives prices up.'),
  mcq('um.terrace', 'urban-models', 'In many British cities, rows of terraced houses near the centre were built mainly…', [['in the 1800s, for factory workers', true], ['in the 1990s for city commuters', false, 'Modern estates are usually further out.'], ['in the 1950s to replace bomb damage', false, 'Post-war housing was mostly estates and tower blocks.'], ['in the countryside for farm workers', false, 'They were built in the inner city.']], 'Workers had to walk to the factories, so housing was packed in close by.'),
  mcq('um.fringe', 'urban-models', 'Which land use is typical of the rural–urban fringe?', [['Retail parks and golf courses', true], ['Skyscraper offices and banks', false, 'Those are in the CBD.'], ['Old Victorian factories', false, 'Those are in the inner city.'], ['City-centre shopping streets', false, 'Those are in the CBD.']], 'Cheap, flat land and easy motorway access attract big developments to the edge of cities.'),
  mcq('um.hoyt', 'urban-models', 'How does the Hoyt sector model differ from the Burgess model?', [['It adds wedges along transport routes', true], ['It only shows the countryside', false, 'It is a city model too.'], ['It puts factories in the outer suburbs', false, 'It shows industry along routes like railways and rivers.'], ['It shows the city as a grid of blocks', false, 'Hoyt added sectors.']], 'Homer Hoyt suggested in 1939 that cities grow outward along roads, railways and rivers.'),
  written('um.w', 'urban-models', 'How well does the Burgess model describe a UK city you know or have studied?', ['Briefly describe the model', 'Where the city fits (CBD, inner city, suburbs, fringe)', 'Where it does not fit (regeneration, out-of-town shopping, social housing on the edge)', 'A judgement'], 'The Burgess model shows a city as rings: a central business district, then an inner city of old housing and industry, inner and outer suburbs, and the rural–urban fringe. London fits this broadly. Its CBD in the City and West End has the tallest, most expensive buildings, many inner areas such as Hackney have dense 1800s terraces, and wealthier, lower-density suburbs spread outwards to the green belt. However, it does not fit perfectly. Regeneration has turned former inner-city docks into the skyscrapers of Canary Wharf, some large council estates were built on the edge of the city, and out-of-town retail parks have drawn shops away from the centre. The model is a useful starting point, but real cities are shaped by transport, planning and history as well as distance from the centre.'),

  // --- resources and conflict (GCSE taster)
  mcq('rc.arctic', 'resources-conflict', 'Why is the Arctic becoming more contested?', [['Melting ice opens routes and resources', true], ['It is getting colder and icier', false, 'It is warming faster than almost anywhere.'], ['Its sea ice is growing every year', false, 'Arctic sea ice is shrinking, not growing.'], ['It is protected like Antarctica', false, 'There is no treaty for the Arctic like the Antarctic Treaty.']], 'Routes such as the Northern Sea Route along Russia’s coast are becoming usable in summer.'),
  mcq('rc.rare', 'resources-conflict', 'Rare earth elements and cobalt are vital for phones, batteries and wind turbines. Why does this matter geographically?', [['They are mined in only a few countries', true], ['They are found in every country', false, 'They are concentrated in a few places.'], ['They are easy to recycle from phones', false, 'Recycling them is still difficult and rare.'], ['They can never run out', false, 'They are finite.']], 'Much of the world’s cobalt comes from the Democratic Republic of the Congo, sometimes in dangerous conditions.'),
  mcq('rc.water', 'resources-conflict', 'Which is the best example of countries COOPERATING over a shared river?', [['A treaty sharing water and flood data', true], ['One country building a dam without telling', false, 'That can cause tension.'], ['Polluting the river upstream', false, 'That harms neighbours downstream.'], ['Closing the river to foreign boats', false, 'That is not cooperation.']], 'The Indus Waters Treaty of 1960 between India and Pakistan lasted for decades despite their rivalry.'),
  mcq('rc.finite', 'resources-conflict', 'Which of these is a NON-RENEWABLE resource?', [['Oil', true], ['Wind', false, 'Wind is renewable.'], ['Sunlight', false, 'Renewable.'], ['Timber from a well-managed forest', false, 'Managed forests can be renewable.']], 'Non-renewable resources such as oil, coal and gas will eventually run out.'),
  written('rc.w', 'resources-conflict', 'Explain why shared or scarce resources can lead to tension between countries. Use at least one example.', ['Why scarcity or sharing causes tension (upstream–downstream, competing claims)', 'A named example (e.g. the Nile, the Euphrates, the Arctic)', 'How tension could be reduced (treaties, data sharing)', 'A brief conclusion'], 'Resources cause tension when they are scarce or when more than one country depends on them. Rivers are a clear example, because the country upstream can control how much water flows downstream. Ethiopia’s Grand Ethiopian Renaissance Dam on the Blue Nile will provide electricity for development, but Egypt, which depends almost entirely on the Nile, fears its water supply will fall. Similarly, as Arctic sea ice melts, countries such as Russia, Canada and Norway are competing to claim newly reachable seabed resources and shipping routes. Tension can be reduced through treaties that share resources fairly, such as the 1960 Indus Waters Treaty between India and Pakistan, and by sharing data and benefits. Cooperation is possible, but it needs trust and agreed rules.'),
];

export default [{ subject: 'geography', deck: 'y8-more', topics, items }];
